import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # High watermark: events with event_ts <= high_ts are already applied.
    high_ts = watermark["high_ts"].iloc[0]

    # Only unapplied events need to be processed.
    pending = events[events["event_ts"] > high_ts].copy()

    # Sequential application order: per item, by (event_ts, event_seq).
    pending = pending.sort_values(
        ["item_id", "event_ts", "event_seq"], kind="mergesort"
    )

    # Build initial snapshot state keyed by item_id.
    snapshot = {}
    for _, row in target.iterrows():
        snapshot[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"],
        }

    for _, ev in pending.iterrows():
        item = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        ts = ev["event_ts"]

        if op == "R":
            if item in snapshot:
                snapshot[item]["qty_on_hand"] = snapshot[item]["qty_on_hand"] + qty
                snapshot[item]["last_event_ts"] = ts
            else:
                # Absent (never existed or previously delisted): start from 0.
                snapshot[item] = {"qty_on_hand": qty, "last_event_ts": ts}
        elif op == "A":
            # Absolute reset, recreating the item if it was delisted/absent.
            snapshot[item] = {"qty_on_hand": qty, "last_event_ts": ts}
        elif op == "D":
            if item in snapshot:
                del snapshot[item]
            # If absent already, delete is a no-op.
        else:
            # Unknown op codes are ignored (defensive; not expected per spec).
            continue

    rows = [
        {
            "item_id": item_id,
            "qty_on_hand": state["qty_on_hand"],
            "last_event_ts": state["last_event_ts"],
        }
        for item_id, state in snapshot.items()
    ]

    new_snapshot = pd.DataFrame(
        rows, columns=["item_id", "qty_on_hand", "last_event_ts"]
    )

    return {"new_snapshot": new_snapshot}
